import { COLOR_IDS, FOOD_IDS, HABITAT_IDS } from "./types";
import type { AnimalOptions, OptionId, OptionTopic, TopicOptions } from "./types";

/**
 * Validates raw JSON (generated by ChatGPT) at load time.
 * Unknown ids and topics are dropped with a console warning instead of breaking the game.
 */

const ALLOWED_IDS: Readonly<Record<OptionTopic, readonly string[]>> = {
  habitat: HABITAT_IDS,
  food: FOOD_IDS,
  color: COLOR_IDS,
};

const TOPICS: readonly OptionTopic[] = ["habitat", "food", "color"];

function isRecord(value: unknown): value is Record<string, unknown> {
  return typeof value === "object" && value !== null && !Array.isArray(value);
}

function parseIds(raw: unknown, topic: OptionTopic, where: string): OptionId[] {
  if (!Array.isArray(raw)) return [];
  const allowed = ALLOWED_IDS[topic];
  return raw.filter((id): id is OptionId => {
    const ok = typeof id === "string" && allowed.includes(id);
    if (!ok) console.warn(`[answer-options] ${where}: unknown ${topic} id "${String(id)}"`);
    return ok;
  });
}

function parseTopic(raw: unknown, topic: OptionTopic, animal: string): TopicOptions | undefined {
  if (!isRecord(raw)) return undefined;
  const where = `${animal}.${topic}`;
  const parsed: TopicOptions = {
    correct: parseIds(raw.correct, topic, where),
    alsoTrue: parseIds(raw.alsoTrue, topic, where),
    easy: parseIds(raw.easy, topic, where),
    medium: parseIds(raw.medium, topic, where),
  };
  if (parsed.correct.length === 0) {
    console.warn(`[answer-options] ${where}: no correct answer, topic skipped`);
    return undefined;
  }
  // A true answer must never be offered as a wrong one
  const trueIds = new Set<OptionId>([...parsed.correct, ...parsed.alsoTrue]);
  const clash = [...parsed.easy, ...parsed.medium].filter((id) => trueIds.has(id));
  if (clash.length > 0) {
    console.warn(`[answer-options] ${where}: true answers used as wrong options: ${clash.join(", ")}`);
    return {
      ...parsed,
      easy: parsed.easy.filter((id) => !trueIds.has(id)),
      medium: parsed.medium.filter((id) => !trueIds.has(id)),
    };
  }
  return parsed;
}

export function parseAnimalOptions(raw: unknown): Map<string, AnimalOptions> {
  const result = new Map<string, AnimalOptions>();
  if (!Array.isArray(raw)) return result;

  for (const item of raw) {
    if (!isRecord(item) || typeof item.animal !== "string" || !isRecord(item.options)) continue;
    const animal = item.animal;
    const rawOptions = item.options;
    const options: Partial<Record<OptionTopic, TopicOptions>> = {};
    for (const topic of TOPICS) {
      const parsed = parseTopic(rawOptions[topic], topic, animal);
      if (parsed) options[topic] = parsed;
    }
    result.set(animal, { animal, options });
  }
  return result;
}
